theorem int_add_neg (a b : Nat) :
    @Quot.mk.{1} (Prod Nat Nat) intRel
        (addRep (@prod_mk Nat Nat a b)
                (negRep (@prod_mk Nat Nat a b))) =
      @Quot.mk.{1} (Prod Nat Nat) intRel
        (@prod_mk Nat Nat Nat.zero Nat.zero)

def addRep (a b : Prod Nat Nat) : Prod Nat Nat :=
  @prod_mk Nat Nat
    (Nat.add (Prod.fst Nat Nat a)
             (Prod.fst Nat Nat b))
    (Nat.add (Prod.snd Nat Nat a)
             (Prod.snd Nat Nat b))
